// Подготовка рецепта для BGE-M3 эмбеддинга
const recipe = $input.first().json;

const fullText = `Рецепт: ${recipe.name}\n\nСодержание: ${recipe.content}`;

const MAX_CHARS = 16000; // BGE-M3 поддерживает 8192 токена

let embeddingText;
if (fullText.length <= MAX_CHARS) {
  embeddingText = fullText;
} else {
  const truncated = fullText.substring(0, MAX_CHARS);
  const lastSpaceIndex = truncated.lastIndexOf(' ');
  if (lastSpaceIndex > MAX_CHARS * 0.9) {
    embeddingText = truncated.substring(0, lastSpaceIndex) + '...';
  } else {
    embeddingText = truncated + '...';
  }
  console.log(`Текст обрезан: ${fullText.length} → ${embeddingText.length}`);
}

return [{
  json: {
    embed_text: embeddingText,
    recipe_data: {
      id: recipe.id,
      number: recipe.number,
      name: recipe.name,
      content: recipe.content,
      full_text: recipe.full_text,
      category: recipe.category || '',
      source_book: recipe.source_book || '',
      source_pattern: recipe.source_pattern || '',
      was_truncated: fullText.length > MAX_CHARS,
      original_length: fullText.length,
      embedding_length: embeddingText.length
    }
  }
}];

// Полный парсер исторических рецептов (BGE-M3 версия — без ручных sparse vectors)
console.log('=== ПОЛНЫЙ ПАРСЕР ИСТОРИЧЕСКИХ РЕЦЕПТОВ (BGE-M3) ===');

// Парсинг эссенций, эликсиров и тинктур
function parseElixirsAndTinctures(text, startRecipeNumber) {
  console.log('\n--- Парсинг эссенций, эликсиров и тинктур ---');
  const recipes = [];
  let nextRecipeNumber = startRecipeNumber;

  const numberedPattern = /§\s*(\d+)\.\s*\n(\d+)\.\s*([^\n]+?)\.\s*\n\s*\n([\s\S]*?)(?=§\s*\d+\.|$)/g;

  let match;
  while ((match = numberedPattern.exec(text)) !== null) {
    const paragraphNumber = parseInt(match[1]);
    const recipeNumber = parseInt(match[2]);
    let name = match[3].trim();
    let content = match[4].trim();

    if (name.includes('ГЛАВА') || name.includes('ОТДЕЛЕНИЕ') || 
        content.length < 50 || content.includes('Стр.')) {
      continue;
    }

    let category = 'настойка';
    if (name.toLowerCase().includes('эссенция') || name.toLowerCase().includes('квинтэссенция')) {
      category = 'эссенция';
    } else if (name.toLowerCase().includes('эликсир')) {
      category = 'эликсир';
    } else if (name.toLowerCase().includes('тинктура')) {
      category = 'тинктура';
    } else if (name.toLowerCase().includes('капли') || name.toLowerCase().includes('жизненные')) {
      category = 'жизненные_капли';
    } else if (name.toLowerCase().includes('вода') && !name.toLowerCase().includes('раневая')) {
      category = 'лечебная_вода';
    }

    if (content.length > 60 && 
        (content.includes('Возьми') || content.includes('настаивай') || content.includes('перегони'))) {

      recipes.push({
        id: `recipe_${nextRecipeNumber}`,
        number: nextRecipeNumber,
        name: name,
        content: content,
        full_text: `${name}\n\n${content}`,
        source_pattern: 'elixir_numbered',
        category: category,
        source_book: 'tinctures',
        original_paragraph: paragraphNumber,
        original_recipe_number: recipeNumber
      });

      console.log(`  ✓ ${name} (${category}, §${paragraphNumber}.${recipeNumber})`);
      nextRecipeNumber++;
    }
  }

  // Простые рецепты без двойной нумерации
  const simplePattern = /§\s*(\d+)\.\s*\n([^\n]+?)\.\s*\n\s*\n([\s\S]*?)(?=§\s*\d+\.|$)/g;

  let simpleMatch;
  while ((simpleMatch = simplePattern.exec(text)) !== null) {
    const paragraphNumber = parseInt(simpleMatch[1]);
    let name = simpleMatch[2].trim();
    let content = simpleMatch[3].trim();

    if (recipes.some(r => r.original_paragraph === paragraphNumber) ||
        name.includes('ГЛАВА') || name.includes('ОТДЕЛЕНИЕ') || 
        content.length < 50) {
      continue;
    }

    let category = 'настойка';
    if (name.toLowerCase().includes('эссенция')) {
      category = 'эссенция';
    } else if (name.toLowerCase().includes('эликсир')) {
      category = 'эликсир';
    } else if (name.toLowerCase().includes('тинктура')) {
      category = 'тинктура';
    }

    if (content.length > 60 && 
        (content.includes('Возьми') || content.includes('настаивай') || content.includes('перегони'))) {

      recipes.push({
        id: `recipe_${nextRecipeNumber}`,
        number: nextRecipeNumber,
        name: name,
        content: content,
        full_text: `${name}\n\n${content}`,
        source_pattern: 'elixir_simple',
        category: category,
        source_book: 'tinctures',
        original_paragraph: paragraphNumber
      });

      console.log(`  ✓ ${name} (${category}, §${paragraphNumber})`);
      nextRecipeNumber++;
    }
  }

  console.log(`Найдено ${recipes.length} рецептов эссенций, эликсиров и тинктур`);
  return { recipes, nextRecipeNumber };
}

// Парсинг благовонных вод
function parsePerfumeWaters(text, startRecipeNumber) {
  console.log('\n--- Парсинг благовонных вод ---');
  const recipes = [];
  let nextRecipeNumber = startRecipeNumber;

  const perfumePattern = /§\s*(\d+)\.\s*\n(\d+)\.\s*([^\n]+?)\.\s*\n([^\n]*?)\.?\s*\n\s*\n([\s\S]*?)(?=§\s*\d+\.|$)/g;

  let match;
  while ((match = perfumePattern.exec(text)) !== null) {
    const paragraphNumber = parseInt(match[1]);
    const recipeNumber = parseInt(match[2]);
    let name = match[3].trim();
    const frenchName = match[4].trim();
    let content = match[5].trim();

    if (content.length > 100 && 
        (content.includes('Возьми') || content.includes('К приготовлению') || content.includes('настаивать'))) {

      if (!name.toLowerCase().includes('вода')) {
        name = `Вода ${name}`;
      }

      recipes.push({
        id: `recipe_${nextRecipeNumber}`,
        number: nextRecipeNumber,
        name: name,
        french_name: frenchName,
        content: content,
        full_text: `${name}\n${frenchName ? frenchName + '\n' : ''}\n${content}`,
        source_pattern: 'perfume_water',
        category: 'благовонная_вода',
        source_book: 'perfume',
        original_paragraph: paragraphNumber,
        original_recipe_number: recipeNumber
      });

      console.log(`  ✓ ${name} (§${paragraphNumber}.${recipeNumber})`);
      nextRecipeNumber++;
    }
  }

  console.log(`Найдено ${recipes.length} благовонных вод`);
  return { recipes, nextRecipeNumber };
}

// Парсинг ароматических масел
function parseAromaticOils(text, startRecipeNumber) {
  console.log('\n--- Парсинг ароматических масел ---');
  const recipes = [];
  let nextRecipeNumber = startRecipeNumber;

  const oilSimplePattern = /§\s*(\d+)\.\s*\n([^\n]+?)\.\s*\n\s*\n([\s\S]*?)(?=§\s*\d+\.|$)/g;

  let match;
  while ((match = oilSimplePattern.exec(text)) !== null) {
    const paragraphNumber = parseInt(match[1]);
    let name = match[2].trim();
    let content = match[3].trim();

    if (name.includes('ГЛАВА') || name.includes('О приготовлении') || content.length < 100) {
      continue;
    }

    if ((name.toLowerCase().includes('масло') || name.toLowerCase().includes('oleum')) &&
        content.length > 80 && 
        (content.includes('Возьми') || content.includes('растолки') || content.includes('перегони'))) {

      recipes.push({
        id: `recipe_${nextRecipeNumber}`,
        number: nextRecipeNumber,
        name: name,
        content: content,
        full_text: `${name}\n\n${content}`,
        source_pattern: 'aromatic_oil',
        category: 'ароматическое_масло',
        source_book: 'oils',
        original_paragraph: paragraphNumber
      });

      console.log(`  ✓ ${name} (§${paragraphNumber})`);
      nextRecipeNumber++;
    }
  }

  console.log(`Найдено ${recipes.length} ароматических масел`);
  return { recipes, nextRecipeNumber };
}

// Основная функция парсинга
async function parseCompleteHistoricalCollection(textData) {
  const allRecipes = [];
  let nextRecipeNumber = 1;

  console.log('\n=== НАЧИНАЕМ ПОЛНЫЙ ПАРСИНГ КОЛЛЕКЦИИ ===');

  const texts = Array.isArray(textData) ? textData : [textData];

  for (let i = 0; i < texts.length; i++) {
    const text = texts[i];
    console.log(`\n--- Обработка текста ${i + 1} (${text.length} символов) ---`);

    try {
      // 1. Водки
      if (text.includes('**')) {
        console.log('\nПарсинг водок...');
        const vodkaPattern = /\*\*(\d+)\.\s*([^*\n]+?)\*\*([\s\S]*?)(?=\*\*\d+\.|$)/g;
        let match;
        let foundVodkaCount = 0;

        while ((match = vodkaPattern.exec(text)) !== null) {
          const number = parseInt(match[1]);
          const name = match[2].trim().replace(/\.$/, '');
          let content = match[3].trim().replace(/^\s*\n+/, '');

          const isChapterHeader = name.includes('ГЛАВА') || name.includes('§') || content.length < 50;

          if (!isChapterHeader && name.length > 3 && content.length > 30) {
            allRecipes.push({
              id: `recipe_${number}`,
              number: number,
              name: name,
              content: content,
              full_text: `${name}\n\n${content}`,
              source_pattern: 'starred_number_title',
              category: 'водка',
              source_book: 'original'
            });

            foundVodkaCount++;
            nextRecipeNumber = Math.max(nextRecipeNumber, number + 1);
          }
        }
        console.log(`✓ Найдено ${foundVodkaCount} рецептов водок`);
      }

      // 2. Французские ликёры
      if (text.includes('§') && !text.includes('эссенция') && !text.includes('тинктура')) {
        console.log('\nПарсинг французских ликёров...');
        let foundFrenchCount = 0;

        const frenchSections = text.split(/(?=§\s*\d+\.)/);
        for (let section of frenchSections) {
          if (section.length < 200) continue;

          const recipePattern = /^(\d+)\.\s*([^\n]+?)\.?\s*\n([\s\S]*?)(?=^\d+\.|$)/gm;
          let recipeMatch;

          while ((recipeMatch = recipePattern.exec(section)) !== null) {
            const recipeNumber = parseInt(recipeMatch[1]);
            let nameAndFrench = recipeMatch[2].trim();
            let content = recipeMatch[3].trim();

            const hasIngredients = content.match(/(?:Возьми|французской водки|настаивать)/i);
            const isTableOfContents = content.length < 80;

            if (hasIngredients && !isTableOfContents && content.length > 50) {
              let displayName = nameAndFrench.startsWith('Вода ') ? 
                nameAndFrench.replace('Вода ', 'Ликёр ') : `Ликёр ${nameAndFrench}`;

              allRecipes.push({
                id: `recipe_${nextRecipeNumber}`,
                number: nextRecipeNumber,
                name: displayName,
                content: content,
                full_text: `${displayName}\n\n${content}`,
                source_pattern: 'french_section',
                category: 'ликёр',
                source_book: 'french',
                original_recipe_number: recipeNumber
              });

              foundFrenchCount++;
              nextRecipeNumber++;
            }
          }
        }
        console.log(`✓ Найдено ${foundFrenchCount} французских ликёров`);
      }

      // 3. Благовонные воды
      if (text.includes('О приготовлении душистых')) {
        const perfumeResult = parsePerfumeWaters(text, nextRecipeNumber);
        allRecipes.push(...perfumeResult.recipes);
        nextRecipeNumber = perfumeResult.nextRecipeNumber;
      }

      // 4. Ароматические масла
      if (text.includes('О приготовлении разных масел')) {
        const oilResult = parseAromaticOils(text, nextRecipeNumber);
        allRecipes.push(...oilResult.recipes);
        nextRecipeNumber = oilResult.nextRecipeNumber;
      }

      // 5. Эссенции, эликсиры и тинктуры
      if (text.includes('эссенций, эликсиров и тинктур') || 
          text.includes('Эссенция') || text.includes('Эликсир') || text.includes('Тинктура')) {
        const elixirResult = parseElixirsAndTinctures(text, nextRecipeNumber);
        allRecipes.push(...elixirResult.recipes);
        nextRecipeNumber = elixirResult.nextRecipeNumber;
      }

    } catch (parseError) {
      console.error(`✗ Ошибка парсинга текста ${i + 1}:`, parseError.message);
    }
  }

  return allRecipes;
}

// Основная функция
try {
  const allInputs = $input.all();
  console.log(`Получено элементов от Merge узла: ${allInputs.length}`);

  let textDataArray = [];

  for (const item of allInputs) {
    if (item?.json) {
      if (item.json.data && typeof item.json.data === 'string' && item.json.data.length > 50000) {
        textDataArray.push(item.json.data);
        console.log(`Найден текст: ${item.json.data.length} символов`);
      }
    }
  }

  console.log(`Текстов: ${textDataArray.length}`);

  if (textDataArray.length === 0) {
    return [{ json: { 
      error: 'Текстовые данные не найдены',
      status: 'failed'
    }}];
  }

  // Парсим все рецепты (без словарей — sparse vectors генерирует BGE-M3)
  const allRecipes = await parseCompleteHistoricalCollection(textDataArray);

  if (allRecipes.length === 0) {
    return [{ json: { 
      error: 'Рецепты не найдены',
      status: 'completed_no_results'
    }}];
  }

  allRecipes.sort((a, b) => a.number - b.number);

  const categoryStats = {};
  allRecipes.forEach(recipe => {
    categoryStats[recipe.category] = (categoryStats[recipe.category] || 0) + 1;
  });

  console.log('\n=== ИТОГОВАЯ СТАТИСТИКА ===');
  console.log(`Обработано рецептов: ${allRecipes.length}`);
  Object.entries(categoryStats).forEach(([cat, count]) => {
    console.log(`  ${cat}: ${count} рецептов`);
  });

  console.log('\n✅ ПОЛНЫЙ ПАРСИНГ КОЛЛЕКЦИИ ЗАВЕРШЕН');

  return allRecipes.map(recipe => ({ json: recipe }));

} catch (globalError) {
  console.error('✗ КРИТИЧЕСКАЯ ОШИБКА:', globalError.message);
  return [{ json: { 
    error: 'Critical parsing error',
    message: globalError.message,
    status: 'failed'
  }}];
}

// Объединение dense + sparse от BGE-M3 для Qdrant
const bgeResponse = $input.last().json;
const recipe = $('Code1').first().json.recipe_data;

// Извлекаем dense и sparse из BGE-M3 ответа
const result = bgeResponse.results[0];
const denseVector = result.dense;
const sparseVector = result.sparse; // {indices: [...], values: [...]}

if (!Array.isArray(denseVector)) {
  throw new Error('Dense вектор не найден в ответе BGE-M3');
}

const uniqueId = recipe.number * 10000 + Date.now() % 10000;

const point = {
  id: Math.abs(uniqueId),
  vector: {
    dense: denseVector,
    sparse: sparseVector
  },
  payload: {
    recipe_id: recipe.id,
    recipe_number: recipe.number,
    recipe_name: recipe.name,
    content: recipe.content,
    full_text: recipe.full_text,
    category: recipe.category || '',
    source: 'tinktures',
    source_book: recipe.source_book || '',
    source_pattern: recipe.source_pattern || '',
    content_length: recipe.content?.length || 0,
    created_at: new Date().toISOString(),
    vector_dimension: denseVector.length,
    sparse_token_count: sparseVector?.indices?.length || 0
  }
};

console.log(`✅ Point: ${recipe.name} (dense=${denseVector.length}d, sparse=${sparseVector?.indices?.length || 0} tokens)`);

return [{
  json: {
    points: [point]
  }
}];
